pub fn caesar(text: Str, shift: Int) -> Str {
  let k = ((shift % 26) + 26) % 26
  var out = ""
  for c in text.chars() {
    let code = c.codes().get_or(0, 0)
    if code >= 65 and code <= 90 {
      let shifted = 65 + (code - 65 + k) % 26
      out = out + shifted.to_char().unwrap_or("")
    } else if code >= 97 and code <= 122 {
      let shifted = 97 + (code - 97 + k) % 26
      out = out + shifted.to_char().unwrap_or("")
    } else {
      out = out + c
    }
  }
  return out
}
